/// Look up GFN0 parameters by atomic number (None when Z > 86).
pub fn get_gfn0_params(z: u8) -> Option<&'static Gfn0ElementParams> {
    if z == 0 || z > 86 {
        return None;
    }
    Some(&GFN0_TABLE[(z - 1) as usize])
}
